import redis, time, collections
src_port, dst_port = 6379, 6380
s0=redis.Redis(host='127.0.0.1',port=src_port)
t0=redis.Redis(host='127.0.0.1',port=dst_port)
assert t0.info('replication')['role']=='master'
assert not any(t0.info('keyspace').get('db'+str(i)) for i in range(16)), 'destination not empty'
assert s0.info('clients')['connected_clients'] <= 2, 'source has other clients: need stable snapshot'
counts=collections.Counter()
for db in range(int(s0.config_get('databases')['databases'])):
    s=redis.Redis(host='127.0.0.1',port=src_port,db=db)
    t=redis.Redis(host='127.0.0.1',port=dst_port,db=db)
    keys=set(s.scan_iter(count=500))
    for key in keys:
        typ=s.type(key)
        if typ==b'none': continue
        exp=s.pexpiretime(key)
        if typ==b'string':
            t.set(key,s.get(key))
        elif typ==b'list':
            vals=s.lrange(key,0,-1);t.rpush(key,*vals)
        elif typ==b'set':
            vals=s.smembers(key);t.sadd(key,*vals)
        elif typ==b'zset':
            vals=s.zrange(key,0,-1,withscores=True);t.zadd(key,dict(vals))
        elif typ==b'hash':
            vals=s.hgetall(key)
            fields=list(vals)
            field_exps=s.execute_command('HPEXPIRETIME',key,'FIELDS',len(fields),*fields)
            t.hset(key,mapping=vals)
            for field,ts in zip(fields,field_exps):
                if ts>0:
                    result=t.execute_command('HPEXPIREAT',key,ts,'FIELDS',1,field)
                    assert result==[1],(key,field,ts,result)
        elif typ==b'stream':
            # Rebuild entries with explicit IDs so streams remain fully writable.
            for batch_start in range(0,s.xlen(key),200):
                # All streams fit a single range in this dataset; this is intentionally checked.
                assert batch_start==0, 'stream exceeds one batch'
                for msgid,fields in s.xrange(key,'-','+'):
                    t.xadd(key,fields,id=msgid)
            info=s.xinfo_stream(key)
            assert info['entries-added']==info['length'] and info['max-deleted-entry-id']==b'0-0', 'stream has history requiring extra metadata'
            for group in s.xinfo_groups(key):
                name=group['name']
                args=['XGROUP','CREATE',key,name,group['last-delivered-id']]
                if group['entries-read'] is not None: args.extend(['ENTRIESREAD',group['entries-read']])
                t.execute_command(*args)
                for consumer in s.xinfo_consumers(key,name):
                    cname=consumer['name']
                    t.execute_command('XGROUP','CREATECONSUMER',key,name,cname)
                start='-'
                while True:
                    pending=s.xpending_range(key,name,start,'+',100)
                    if not pending: break
                    for item in pending:
                        msgid=item['message_id']
                        # FORCE creates a pending entry; TIME and RETRYCOUNT preserve delivery metadata.
                        delivered=int(time.time()*1000)-item['time_since_delivered']
                        reply=t.execute_command('XCLAIM',key,name,item['consumer'],0,msgid,'TIME',delivered,'RETRYCOUNT',item['times_delivered'],'FORCE','JUSTID')
                        assert reply==[msgid],(key,name,msgid,reply)
                    start='('+pending[-1]['message_id'].decode()
        else:
            raise RuntimeError((key,typ))
        if exp>0:
            assert t.pexpireat(key,exp), (key,exp)
        counts[(db,typ.decode())]+=1
    if keys: print('copied db',db,'keys',len(keys),flush=True)
print('copied counts',counts,flush=True)
# Verify all keys and their contents, absolute expiry timestamps, and stream consumer group state.
for db in range(int(s0.config_get('databases')['databases'])):
    s=redis.Redis(host='127.0.0.1',port=src_port,db=db)
